use vstd::prelude::*;

verus! {
    // Return the index of the first occurrence of the maximum element
    // in a non‐empty Vec<i8>.
    fn nanargmax(a: Vec<i8>) -> (idx: usize)
        requires
            a.len() > 0,
        ensures
            // The result is in bounds
            idx < a.len(),
            // The chosen element is at least as large as every element
            forall j: usize :: j < a.len() ==> a.index(idx) >= a.index(j),
            // And it is the *first* occurrence of that maximum
            forall k: usize :: k < idx ==> a.index(idx) > a.index(k),
    {
        // We keep track of the best index and its value so far
        let mut max_idx: usize = 0;
        let mut max_val: i8    = a.index(0);
        let mut i: usize       = 1;

        // We scan from i = 1 up to a.len()
        while i < a.len()
            invariant
                // i walks from 1..=a.len()
                1 <= i && i <= a.len(),
                // max_idx is always < i
                max_idx < i,
                // max_val is really the array at max_idx
                max_val == a.index(max_idx),
                // max_val is ≥ every a[j] for j < i
                forall j: usize :: j < i ==> max_val >= a.index(j),
                // moreover it's strictly larger than all previous slots
                forall k: usize :: k < max_idx ==> max_val > a.index(k),
            decreases a.len() - i,
        {
            let ai = a.index(i);
            if ai > max_val {
                // We are about to update to a new maximum at position i.
                // We must show ai is strictly greater than *all* a[k] for k<i.
                assert(forall k: usize :: k < i ==> ai > a.index(k)) by {
                    // Let k be arbitrary with k<i.
                    intros k;
                    assume(k < i);
                    // By the loop invariant we know a.index(k) ≤ max_val,
                    assert(a.index(k) <= max_val);
                    // and by the branch condition ai > max_val,
                    assert(ai > max_val);
                    // hence ai > a.index(k).
                };
                max_val = ai;
                max_idx = i;
            }
            i = i + 1;
        }

        // At exit i == a.len(), so the invariants yield the postcondition.
        idx = max_idx;
    }
}

